await say(doc.chat_id, text, {
  reply_markup: {
    inline_keyboard: [[
      { text: 'Approve', callback_data: `approve:${doc.id}` },
      { text: 'Reject', callback_data: `reject:${doc.id}` },
    ]],
  },
});
return [{ json: doc }];

